package com.devs.accountant.transaction.dto;

import com.devs.accountant.transaction.TransactionType;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;

/**
 * One transaction of a batch. {@code uuid} is generated by the client. {@code fee} defaults to 0.
 * {@code originApplied} / {@code destinationApplied} (default true) say whether the amount is already reflected on each
 * side: the origin may stay unapplied in EXPENSE, TRANSFER, INVEST and PROFIT; the destination in TRANSFER, INVEST,
 * PROFIT and DIVIDEND.
 */
public record TransactionRequest(
        @NotNull UUID uuid,
        @NotNull TransactionType type,
        @NotNull Long originAccountId,
        Long destinationAccountId,

        @NotNull @Positive @Digits(integer = 17, fraction = 2)
        BigDecimal amount,

        @PositiveOrZero @Digits(integer = 17, fraction = 2) BigDecimal fee,
        @NotBlank @Size(min = 3, max = 255) String description,
        Boolean originApplied,
        Boolean destinationApplied,
        @NotNull LocalDateTime operationDate,
        Long scheduleId) {

    public boolean isOriginApplied() {
        return originApplied == null || originApplied;
    }

    public boolean isDestinationApplied() {
        return destinationApplied == null || destinationApplied;
    }
}
